// loginURLKeysAvailable reports whether the controlling terminal can deliver
// single keypresses, so the prompt only offers actions readLoginURLAction can
// honor. Probing costs an open/close and never consumes input.
func loginURLKeysAvailable() bool {
	if interactive.UnderTest() {
		return false
	}

	tty, err := openLoginURLTTY()
	if err != nil {
		return false
	}
	defer tty.Close()

	return interactive.IsTerminalReader(tty)
}

